import React, { useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import axios from "axios";

function PaymentPage() {
  const navigate = useNavigate();
  const location = useLocation();

  const [paymentMethod, setPaymentMethod] = useState("");
  const [formData, setFormData] = useState({
    cardNumber: "",
    expiry: "",
    cvv: "",
    upiId: "",
    bankName: "",
    accountNumber: ""
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const validateCardNumber = (num) => {
    const onlyDigits = num.replace(/\D/g, ""); 
    return onlyDigits.length >= 13 && onlyDigits.length <= 19;
  };

  const validateExpiry = (exp) => {
    if (!/^\d{2}\/\d{2}$/.test(exp)) return false;
    const [month, year] = exp.split("/").map(Number);
    const currentDate = new Date();
    const currentYear = currentDate.getFullYear() % 100; 
    const currentMonth = currentDate.getMonth() + 1;
    return year > currentYear || (year === currentYear && month >= currentMonth);
  };

  const validateCVV = (cvv) => {
    return /^\d{3,4}$/.test(cvv);
  };

  const handlePayment = async () => {
    // Payment Validation
    if (paymentMethod === "card") {
      if (!validateCardNumber(formData.cardNumber)) {
        alert("Invalid card number. Must be 13–19 digits.");
        return;
      }
      if (!validateExpiry(formData.expiry)) {
        alert("Invalid expiry date. Use MM/YY and ensure it's in the future.");
        return;
      }
      if (!validateCVV(formData.cvv)) {
        alert("Invalid CVV. Must be 3 or 4 digits.");
        return;
      }
    } else if (paymentMethod === "upi") {
      if (!formData.upiId.includes("@")) {
        alert("Invalid UPI ID.");
        return;
      }
    } else if (paymentMethod === "netbanking") {
      if (!formData.bankName || !formData.accountNumber) {
        alert("Please fill all Net Banking details.");
        return;
      }
    } else {
      alert("Please select a payment method.");
      return;
    }

    try {
      // Send booking and trigger email
      const userId = localStorage.getItem("userId"); // logged-in user
      const parkingSlotId = location.state.slotNumber; // assuming slotNumber from booking

      await axios.post(`http://localhost:8081/api/bookings`, location.state, {
        params: {
          userId: userId,
          parkingSlotId: parkingSlotId
        }
      });

      alert("Payment successful! Booking confirmation sent to your email.");
      navigate("/success", { state: location.state });

    } catch (error) {
      console.error("Error sending booking/email:", error);
      alert("Payment failed or email could not be sent.");
    }
  };

  return (
    <div style={styles.container}>
      <h1>Payment Page</h1>

      <div style={styles.selectWrapper}>
        <select
          value={paymentMethod}
          onChange={(e) => setPaymentMethod(e.target.value)}
          style={styles.select}
        >
          <option value="">Select Payment Method</option>
          <option value="card">Credit/Debit Card</option>
          <option value="upi">UPI</option>
          <option value="netbanking">Net Banking</option>
        </select>
      </div>

      {paymentMethod === "card" && (
        <>
          <input
            type="text"
            name="cardNumber"
            placeholder="Card Number"
            value={formData.cardNumber}
            onChange={handleChange}
            style={styles.input}
          />
          <input
            type="text"
            name="expiry"
            placeholder="Expiry Date (MM/YY)"
            value={formData.expiry}
            onChange={handleChange}
            style={styles.input}
          />
          <input
            type="password"
            name="cvv"
            placeholder="CVV"
            value={formData.cvv}
            onChange={handleChange}
            style={styles.input}
          />
        </>
      )}

      {paymentMethod === "upi" && (
        <input
          type="text"
          name="upiId"
          placeholder="Enter UPI ID (e.g., name@upi)"
          value={formData.upiId}
          onChange={handleChange}
          style={styles.input}
        />
      )}

      {paymentMethod === "netbanking" && (
        <>
          <input
            type="text"
            name="bankName"
            placeholder="Bank Name"
            value={formData.bankName}
            onChange={handleChange}
            style={styles.input}
          />
          <input
            type="text"
            name="accountNumber"
            placeholder="Account Number"
            value={formData.accountNumber}
            onChange={handleChange}
            style={styles.input}
          />
        </>
      )}

      <button style={styles.button} onClick={handlePayment}>
        Pay & Confirm
      </button>
    </div>
  );
}



export default PaymentPage;
